INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (1, 0, 0, 'A strange seed was planted on its back at birth. The plant sprouts and grows with this POKéMON.', '0.7 m', 69, 'Bulbasaur', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (2, 0, 0, 'When the bulb on its back grows large, it appears to lose the ability to stand on its hind legs.', '1 m', 130, 'Ivysaur', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (3, 0, 0, 'The plant blooms when it is absorbing solar energy. It stays on the move to seek sunlight.', '2 m', 1000, 'Venusaur', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (4, 0, 0, 'Obviously prefers hot places. When it rains, steam is said to spout from the tip of its tail.', '0.6 m', 85, 'Charmander', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (5, 0, 0, 'When it swings its burning tail, it elevates the temperature to unbearably high levels.', '1.1 m', 190, 'Charmeleon', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (6, 0, 0, 'Spits fire that is hot enough to melt boulders. Known to cause forest fires unintentionally.', '1.7 m', 905, 'Charizard', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (7, 0, 0, 'After birth, its back swells and hardens into a shell. Powerfully sprays foam from its mouth.', '0.5 m', 90, 'Squirtle', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (8, 0, 0, 'Often hides in water to stalk unwary prey. For swimming fast, it moves its ears to maintain balance.', '1 m', 225, 'Wartortle', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (9, 0, 0, 'A brutal POKéMON with pressurized water jets on its shell. They are used for high speed tackles.', '1.6 m', 855, 'Blastoise', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (10, 0, 0, 'Its short feet are tipped with suction pads that enable it to tirelessly climb slopes and walls.', '0.3 m', 29, 'Caterpie', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (11, 0, 0, 'This POKéMON is vulnerable to attack while its shell is soft, exposing its weak and tender body.', '0.7 m', 99, 'Metapod', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (12, 0, 0, 'In battle, it flaps its wings at high speed to release highly toxic dust into the air.', '1.1 m', 320, 'Butterfree', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (13, 0, 0, 'Often found in forests, eating leaves. It has a sharp venomous stinger on its head.', '0.3 m', 32, 'Weedle', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (14, 0, 0, 'Almost incapable of moving, this POKéMON can only harden its shell to protect itself from predators.', '0.6 m', 100, 'Kakuna', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (15, 0, 0, 'Flies at high speed and attacks using its large venomous stingers on its forelegs and tail.', '1 m', 295, 'Beedrill', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (16, 0, 0, 'A common sight in forests and woods. It flaps its wings at ground level to kick up blinding sand.', '0.3 m', 18, 'Pidgey', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (17, 0, 0, 'Very protective of its sprawling territorial area, this POKéMON will fiercely peck at any intruder.', '1.1 m', 300, 'Pidgeotto', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (18, 0, 0, 'When hunting, it skims the surface of water at high speed to pick off unwary prey such as MAGIKARP.', '1.5 m', 395, 'Pidgeot', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (19, 0, 0, 'Bites anything when it attacks. Small and very quick, it is a common sight in many places.', '0.3 m', 35, 'Rattata', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (20, 0, 0, 'It uses its whis­ kers to maintain its balance. It apparently slows down if they are cut off.', '0.7 m', 185, 'Raticate', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (21, 0, 0, 'Eats bugs in grassy areas. It has to flap its short wings at high speed to stay airborne.', '0.3 m', 20, 'Spearow', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (22, 0, 0, 'With its huge and magnificent wings, it can keep aloft without ever having to land for rest.', '1.2 m', 380, 'Fearow', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (23, 0, 0, 'Moves silently and stealthily. Eats the eggs of birds, such as PIDGEY and SPEAROW, whole.', '2 m', 69, 'Ekans', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (24, 0, 0, 'It is rumored that the ferocious warning markings on its belly differ from area to area.', '3.5 m', 650, 'Arbok', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (25, 0, 0, 'When several of these POKéMON gather, their electricity could build and cause lightning storms.', '0.4 m', 60, 'Pikachu', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (26, 0, 0, 'Its long tail serves as a ground to protect itself from its own high voltage power.', '0.8 m', 300, 'Raichu', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (27, 0, 0, 'Burrows deep underground in arid locations far from water. It only emerges to hunt for food.', '0.6 m', 120, 'Sandshrew', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (28, 0, 0, 'Curls up into a spiny ball when threatened. It can roll while curled up to attack or escape.', '1 m', 295, 'Sandslash', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (29, 0, 0, 'Although small, its venomous barbs render this POKéMON dangerous. The female has smaller horns.', '0.4 m', 70, 'Nidoran♀', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (30, 0, 0, 'The female''s horn develops slowly. Prefers physical attacks such as clawing and biting.', '0.8 m', 200, 'Nidorina', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (31, 0, 0, 'Its hard scales provide strong protection. It uses its hefty bulk to execute powerful moves.', '1.3 m', 600, 'Nidoqueen', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (32, 0, 0, 'Stiffens its ears to sense danger. The larger its horns, the more powerful its secreted venom.', '0.5 m', 90, 'Nidoran♂', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (33, 0, 0, 'An aggressive POKéMON that is quick to attack. The horn on its head secretes a powerful venom.', '0.9 m', 195, 'Nidorino', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (34, 0, 0, 'It uses its powerful tail in battle to smash, constrict, then break the prey''s bones.', '1.4 m', 620, 'Nidoking', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (35, 0, 0, 'Its magical and cute appeal has many admirers. It is rare and found only in certain areas.', '0.6 m', 75, 'Clefairy', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (36, 0, 0, 'A timid fairy POKéMON that is rarely seen. It will run and hide the moment it senses people.', '1.3 m', 400, 'Clefable', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (37, 0, 0, 'At the time of birth, it has just one tail. The tail splits from its tip as it grows older.', '0.6 m', 99, 'Vulpix', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (38, 0, 0, 'Very smart and very vengeful. Grabbing one of its many tails could result in a 1000-year curse.', '1.1 m', 199, 'Ninetales', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (39, 0, 0, 'When its huge eyes light up, it sings a mysteriously soothing melody that lulls its enemies to sleep.', '0.5 m', 55, 'Jigglypuff', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (40, 0, 0, 'The body is soft and rubbery. When angered, it will suck in air and inflate itself to an enormous size.', '1 m', 120, 'Wigglytuff', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (41, 0, 0, 'Forms colonies in perpetually dark places. Uses ultrasonic waves to identify and approach targets.', '0.8 m', 75, 'Zubat', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (42, 0, 0, 'Once it strikes, it will not stop draining energy from the victim even if it gets too heavy to fly.', '1.6 m', 550, 'Golbat', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (43, 0, 0, 'During the day, it keeps its face buried in the ground. At night, it wanders around sowing its seeds.', '0.5 m', 54, 'Oddish', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (44, 0, 0, 'The fluid that oozes from its mouth isn''t drool. It is a nectar that is used to attract prey.', '0.8 m', 86, 'Gloom', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (45, 0, 0, 'The larger its petals, the more toxic pollen it contains. Its big head is heavy and hard to hold up.', '1.2 m', 186, 'Vileplume', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (46, 0, 0, 'Burrows to suck tree roots. The mushrooms on its back grow by draw­ ing nutrients from the bug host.', '0.3 m', 54, 'Paras', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (47, 0, 0, 'A host-parasite pair in which the parasite mushroom has taken over the host bug. Prefers damp places.', '1 m', 295, 'Parasect', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (48, 0, 0, 'Lives in the shadows of tall trees where it eats insects. It is attracted by light at night.', '1 m', 300, 'Venonat', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (49, 0, 0, 'The dust-like scales covering its wings are color coded to indicate the kinds of poison it has.', '1.5 m', 125, 'Venomoth', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (50, 0, 0, 'Lives about one yard underground where it feeds on plant roots. It sometimes appears above ground.', '0.2 m', 8, 'Diglett', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (51, 0, 0, 'A team of DIGLETT triplets. It triggers huge earthquakes by burrowing 60 miles underground.', '0.7 m', 333, 'Dugtrio', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (52, 0, 0, 'Adores circular objects. Wanders the streets on a nightly basis to look for dropped loose change.', '0.4 m', 42, 'Meowth', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (53, 0, 0, 'Although its fur has many admirers, it is tough to raise as a pet because of its fickle meanness.', '1 m', 320, 'Persian', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (54, 0, 0, 'While lulling its enemies with its vacant look, this wily POKéMON will use psychokinetic powers.', '0.8 m', 196, 'Psyduck', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (55, 0, 0, 'Often seen swim­ ming elegantly by lake shores. It is often mistaken for the Japanese monster, Kappa.', '1.7 m', 766, 'Golduck', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (56, 0, 0, 'Extremely quick to anger. It could be docile one moment then thrashing away the next instant.', '0.5 m', 280, 'Mankey', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (57, 0, 0, 'Always furious and tenacious to boot. It will not abandon chasing its quarry until it is caught.', '1 m', 320, 'Primeape', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (58, 0, 0, 'Very protective of its territory. It will bark and bite to repel intruders from its space.', '0.7 m', 190, 'Growlithe', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (59, 0, 0, 'A POKéMON that has been admired since the past for its beauty. It runs agilely as if on wings.', '1.9 m', 1550, 'Arcanine', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (60, 0, 0, 'Its newly grown legs prevent it from running. It appears to prefer swimming than trying to stand.', '0.6 m', 124, 'Poliwag', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (61, 0, 0, 'Capable of living in or out of water. When out of water, it sweats to keep its body slimy.', '1 m', 200, 'Poliwhirl', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (62, 0, 0, 'An adept swimmer at both the front crawl and breast stroke. Easily overtakes the best human swimmers.', '1.3 m', 540, 'Poliwrath', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (63, 0, 0, 'Using its ability to read minds, it will identify impending danger and TELEPORT to safety.', '0.9 m', 195, 'Abra', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (64, 0, 0, 'It emits special alpha waves from its body that induce headaches just by being close by.', '1.3 m', 565, 'Kadabra', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (65, 0, 0, 'Its brain can out­ perform a super­ computer. Its intelligence quotient is said to be 5,000.', '1.5 m', 480, 'Alakazam', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (66, 0, 0, 'Loves to build its muscles. It trains in all styles of martial arts to become even stronger.', '0.8 m', 195, 'Machop', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (67, 0, 0, 'Its muscular body is so powerful, it must wear a power save belt to be able to regulate its motions.', '1.5 m', 705, 'Machoke', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (68, 0, 0, 'Using its heavy muscles, it throws powerful punches that can send the victim clear over the horizon.', '1.6 m', 1300, 'Machamp', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (69, 0, 0, 'A carnivorous POKéMON that traps and eats bugs. It uses its root feet to soak up needed moisture.', '0.7 m', 40, 'Bellsprout', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (70, 0, 0, 'It spits out POISONPOWDER to immobilize the enemy and then finishes it with a spray of ACID.', '1 m', 64, 'Weepinbell', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (71, 0, 0, 'Said to live in huge colonies deep in jungles, although no one has ever returned from there.', '1.7 m', 155, 'Victreebel', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (72, 0, 0, 'Drifts in shallow seas. Anglers who hook them by accident are often punished by its stinging acid.', '0.9 m', 455, 'Tentacool', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (73, 0, 0, 'The tentacles are normally kept short. On hunts, they are extended to ensnare and immobilize prey.', '1.6 m', 550, 'Tentacruel', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (74, 0, 0, 'Found in fields and mountains. Mistaking them for boulders, people often step or trip on them.', '0.4 m', 200, 'Geodude', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (75, 0, 0, 'Rolls down slopes to move. It rolls over any obstacle without slowing or changing its direction.', '1 m', 1050, 'Graveler', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (76, 0, 0, 'Its boulder-like body is extremely hard. It can easily withstand dynamite blasts without damage.', '1.4 m', 3000, 'Golem', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (77, 0, 0, 'Its hooves are 10 times harder than diamonds. It can trample anything completely flat in little time.', '1 m', 300, 'Ponyta', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (78, 0, 0, 'Very competitive, this POKéMON will chase anything that moves fast in the hopes of racing it.', '1.7 m', 950, 'Rapidash', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (79, 0, 0, 'Incredibly slow and dopey. It takes 5 seconds for it to feel pain when under attack.', '1.2 m', 360, 'Slowpoke', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (80, 0, 0, 'The SHELLDER that is latched onto SLOWPOKE''s tail is said to feed on the host''s left over scraps.', '1.6 m', 785, 'Slowbro', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (81, 0, 0, 'Uses anti-gravity to stay suspended. Appears without warning and uses THUNDER WAVE and similar moves.', '0.3 m', 60, 'Magnemite', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (82, 0, 0, 'Formed by several MAGNEMITEs linked together. They frequently appear when sunspots flare up.', '1 m', 600, 'Magneton', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (83, 0, 0, 'The sprig of green onions it holds is its weapon. It is used much like a metal sword.', '0.8 m', 150, 'Farfetch’d', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (84, 0, 0, 'A bird that makes up for its poor flying with its fast foot speed. Leaves giant footprints.', '1.4 m', 392, 'Doduo', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (85, 0, 0, 'Uses its three brains to execute complex plans. While two heads sleep, one head stays awake.', '1.8 m', 852, 'Dodrio', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (86, 0, 0, 'The protruding horn on its head is very hard. It is used for bashing through thick ice.', '1.1 m', 900, 'Seel', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (87, 0, 0, 'Stores thermal energy in its body. Swims at a steady 8 knots even in intensely cold waters.', '1.7 m', 1200, 'Dewgong', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (88, 0, 0, 'Appears in filthy areas. Thrives by sucking up polluted sludge that is pumped out of factories.', '0.9 m', 300, 'Grimer', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (89, 0, 0, 'Thickly covered with a filthy, vile sludge. It is so toxic, even its footprints contain poison.', '1.2 m', 300, 'Muk', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (90, 0, 0, 'Its hard shell repels any kind of attack. It is vulnerable only when its shell is open.', '0.3 m', 40, 'Shellder', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (91, 0, 0, 'When attacked, it launches its horns in quick volleys. Its innards have never been seen.', '1.5 m', 1325, 'Cloyster', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (92, 0, 0, 'Almost invisible, this gaseous POKéMON cloaks the target and puts it to sleep without notice.', '1.3 m', 1, 'Gastly', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (93, 0, 0, 'Because of its ability to slip through block walls, it is said to be from an­ other dimension.', '1.6 m', 1, 'Haunter', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (94, 0, 0, 'Under a full moon, this POKéMON likes to mimic the shadows of people and laugh at their fright.', '1.5 m', 405, 'Gengar', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (95, 0, 0, 'As it grows, the stone portions of its body harden to become similar to a diamond, but colored black.', '8.8 m', 2100, 'Onix', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (96, 0, 0, 'Puts enemies to sleep then eats their dreams. Occasionally gets sick from eating bad dreams.', '1 m', 324, 'Drowzee', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (97, 0, 0, 'When it locks eyes with an enemy, it will use a mix of PSI moves such as HYPNOSIS and CONFUSION.', '1.6 m', 756, 'Hypno', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (98, 0, 0, 'Its pincers are not only powerful weapons, they are used for balance when walking sideways.', '0.4 m', 65, 'Krabby', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (99, 0, 0, 'The large pincer has 10000 hp of crushing power. However, its huge size makes it unwieldy to use.', '1.3 m', 600, 'Kingler', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (100, 0, 0, 'Usually found in power plants. Easily mistaken for a POKé BALL, they have zapped many people.', '0.5 m', 104, 'Voltorb', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (101, 0, 0, 'It stores electric energy under very high pressure. It often explodes with little or no provocation.', '1.2 m', 666, 'Electrode', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (102, 0, 0, 'Often mistaken for eggs. When disturbed, they quickly gather and attack in swarms.', '0.4 m', 25, 'Exeggcute', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (103, 0, 0, 'Legend has it that on rare occasions, one of its heads will drop off and continue on as an EXEGGCUTE.', '2 m', 1200, 'Exeggutor', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (104, 0, 0, 'Because it never removes its skull helmet, no one has ever seen this POKéMON''s real face.', '0.4 m', 65, 'Cubone', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (105, 0, 0, 'The bone it holds is its key weapon. It throws the bone skillfully like a boomerang to KO targets.', '1 m', 450, 'Marowak', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (106, 0, 0, 'When in a hurry, its legs lengthen progressively. It runs smoothly with extra long, loping strides.', '1.5 m', 498, 'Hitmonlee', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (107, 0, 0, 'While apparently doing nothing, it fires punches in lightning fast volleys that are impossible to see.', '1.4 m', 502, 'Hitmonchan', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (108, 0, 0, 'Its tongue can be extended like a chameleon''s. It leaves a tingling sensation when it licks enemies.', '1.2 m', 655, 'Lickitung', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (109, 0, 0, 'Because it stores several kinds of toxic gases in its body, it is prone to exploding without warning.', '0.6 m', 10, 'Koffing', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (110, 0, 0, 'Where two kinds of poison gases meet, 2 KOFFINGs can fuse into a WEEZING over many years.', '1.2 m', 95, 'Weezing', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (111, 0, 0, 'Its massive bones are 1000 times harder than human bones. It can easily knock a trailer flying.', '1 m', 1150, 'Rhyhorn', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (112, 0, 0, 'Protected by an armor-like hide, it is capable of living in molten lava of 3,600 degrees.', '1.9 m', 1200, 'Rhydon', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (113, 0, 0, 'A rare and elusive POKéMON that is said to bring happiness to those who manage to get it.', '1.1 m', 346, 'Chansey', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (114, 0, 0, 'The whole body is swathed with wide vines that are similar to sea­ weed. Its vines shake as it walks.', '1 m', 350, 'Tangela', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (115, 0, 0, 'The infant rarely ventures out of its mother''s protective pouch until it is 3 years old.', '2.2 m', 800, 'Kangaskhan', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (116, 0, 0, 'Known to shoot down flying bugs with precision blasts of ink from the surface of the water.', '0.4 m', 80, 'Horsea', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (117, 0, 0, 'Capable of swim­ ming backwards by rapidly flapping its wing-like pectoral fins and stout tail.', '1.2 m', 250, 'Seadra', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (118, 0, 0, 'Its tail fin billows like an elegant ballroom dress, giving it the nickname of the Water Queen.', '0.6 m', 150, 'Goldeen', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (119, 0, 0, 'In the autumn spawning season, they can be seen swimming power­ fully up rivers and creeks.', '1.3 m', 390, 'Seaking', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (120, 0, 0, 'An enigmatic POKéMON that can effortlessly regenerate any appendage it loses in battle.', '0.8 m', 345, 'Staryu', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (121, 0, 0, 'Its central core glows with the seven colors of the rainbow. Some people value the core as a gem.', '1.1 m', 800, 'Starmie', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (122, 0, 0, 'If interrupted while it is miming, it will slap around the offender with its broad hands.', '1.3 m', 545, 'Mr. Mime', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (123, 0, 0, 'With ninja-like agility and speed, it can create the illusion that there is more than one.', '1.5 m', 560, 'Scyther', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (124, 0, 0, 'It seductively wiggles its hips as it walks. It can cause people to dance in unison with it.', '1.4 m', 406, 'Jynx', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (125, 0, 0, 'Normally found near power plants, they can wander away and cause major blackouts in cities.', '1.1 m', 300, 'Electabuzz', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (126, 0, 0, 'Its body always burns with an orange glow that enables it to hide perfectly among flames.', '1.3 m', 445, 'Magmar', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (127, 0, 0, 'If it fails to crush the victim in its pincers, it will swing it around and toss it hard.', '1.5 m', 550, 'Pinsir', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (128, 0, 0, 'When it targets an enemy, it charges furiously while whipping its body with its long tails.', '1.4 m', 884, 'Tauros', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (129, 0, 0, 'In the distant past, it was somewhat stronger than the horribly weak descendants that exist today.', '0.9 m', 100, 'Magikarp', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (130, 0, 0, 'Rarely seen in the wild. Huge and vicious, it is capable of destroying entire cities in a rage.', '6.5 m', 2350, 'Gyarados', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (131, 0, 0, 'A POKéMON that has been over­ hunted almost to extinction. It can ferry people across the water.', '2.5 m', 2200, 'Lapras', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (132, 0, 0, 'Capable of copying an enemy''s genetic code to instantly transform itself into a duplicate of the enemy.', '0.3 m', 40, 'Ditto', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (133, 0, 0, 'Its genetic code is irregular. It may mutate if it is exposed to radiation from element STONEs.', '0.3 m', 65, 'Eevee', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (134, 0, 0, 'Lives close to water. Its long tail is ridged with a fin which is often mistaken for a mermaid''s.', '1 m', 290, 'Vaporeon', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (135, 0, 0, 'It accumulates negative ions in the atmosphere to blast out 10000- volt lightning bolts.', '0.8 m', 245, 'Jolteon', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (136, 0, 0, 'When storing thermal energy in its body, its temperature could soar to over 1600 degrees.', '0.9 m', 250, 'Flareon', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (137, 0, 0, 'A POKéMON that consists entirely of programming code. Capable of moving freely in cyberspace.', '0.8 m', 365, 'Porygon', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (138, 0, 0, 'Although long extinct, in rare cases, it can be genetically resurrected from fossils.', '0.4 m', 75, 'Omanyte', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (139, 0, 0, 'A prehistoric POKéMON that died out when its heavy shell made it impossible to catch prey.', '1 m', 350, 'Omastar', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (140, 0, 0, 'A POKéMON that was resurrected from a fossil found in what was once the ocean floor eons ago.', '0.5 m', 115, 'Kabuto', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (141, 0, 0, 'Its sleek shape is perfect for swim­ ming. It slashes prey with its claws and drains the body fluids.', '1.3 m', 405, 'Kabutops', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (142, 0, 0, 'A ferocious, pre­ historic POKéMON that goes for the enemy''s throat with its serrated saw-like fangs.', '1.8 m', 590, 'Aerodactyl', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (143, 0, 0, 'Very lazy. Just eats and sleeps. As its rotund bulk builds, it becomes steadily more slothful.', '2.1 m', 4600, 'Snorlax', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (144, 0, 0, 'A legendary bird POKéMON that is said to appear to doomed people who are lost in icy mountains.', '1.7 m', 554, 'Articuno', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (145, 0, 0, 'A legendary bird POKéMON that is said to appear from clouds while dropping enormous lightning bolts.', '1.6 m', 526, 'Zapdos', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (146, 0, 0, 'Known as the legendary bird of fire. Every flap of its wings creates a dazzling flash of flames.', '2 m', 600, 'Moltres', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (147, 0, 0, 'Long considered a mythical POKéMON until recently when a small colony was found living underwater.', '1.8 m', 33, 'Dratini', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (148, 0, 0, 'A mystical POKéMON that exudes a gentle aura. Has the ability to change climate conditions.', '4 m', 165, 'Dragonair', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (149, 0, 0, 'An extremely rarely seen marine POKéMON. Its intelligence is said to match that of humans.', '2.2 m', 2100, 'Dragonite', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (150, 0, 0, 'It was created by a scientist after years of horrific gene splicing and DNA engineering experiments.', '2 m', 1220, 'Mewtwo', , );
INSERT INTO POKEDEX_ENTRY (Pokedex_Number, Is_Seen, Is_Caught, Description, Height, Weight, Species_Name, Normal_Sprite, Shiny_Sprite) VALUES (151, 0, 0, 'So rare that it is still said to be a mirage by many experts. Only a few people have seen it worldwide.', '0.4 m', 40, 'Mew', , );
