INSERT INTO `MOVE` (Move_Name, Move_Description, Move_Type, Power, Accuracy) VALUES ('Yawn', 'Lulls the foe into yawning, then sleeping next turn.', 'normal', NULL, NULL);
INSERT INTO `MOVE` (Move_Name, Move_Description, Move_Type, Power, Accuracy) VALUES ('Zap Cannon', 'An attack that always paralyzes.', 'electric', 120, 50);
INSERT INTO `MOVE` (Move_Name, Move_Description, Move_Type, Power, Accuracy) VALUES ('Zen Headbutt', 'The user focuses its willpower to its head and rams the foe. It may also make the target flinch.', 'psychic', 80, 90);
